  "claim": {
    "component_id": "C035.component",
    "value": "Ambiguous identifiers may affect record paths.",
    "scope": "A possible limitation of the documentary reconstruction; no particular identifier is judged ambiguous.",
    "provenance": {
      "refs": [
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly identifies ambiguous identifiers as a possible limitation of record paths."
    }
  },
  "signal_basis": {
    "component_id": "C035.signal_basis",
    "value": "Trace records from purported approval to order placement and attachment, record order identifiers, and assess whether approval records link to the relevant order and precede placement.",
    "scope": "Documentary reconstruction of the flagged orders; these checks are proposed observations, without an asserted finding of identifier ambiguity.",
    "provenance": {
      "refs": [
